    write_data<real_type, typename Config::OutputState::shape_prevalence>(state.prevalence, out.hv->prevalence, out.hv->prevalence_length, "prevalence");
    write_data<real_type, typename Config::OutputState::shape_total_prevalence>(state.total_prevalence, out.hv->total_prevalence, out.hv->total_prevalence_length, "total_prevalence");
